import { notFound } from "next/navigation";
import { getIphoneByDocumentId } from "@/services/iphones";
import ImageGallery from "@/components/ImageGallery";
import Link from "next/link";
import { getImageUrl } from "@/services/strapi-image"; 

interface Props {
  params: Promise<{
    documentId: string;
  }>;
}

export default async function DetalleIphonePage({ params }: Props) {
  const { documentId } = await params;
  const iphone = await getIphoneByDocumentId(documentId);

  if (!iphone) {
    notFound();
  }

  const descripLines = iphone.descrip ? iphone.descrip.split('\n') : [];

  const urlsAbsolutas = iphone.fotos && iphone.fotos.length > 0
    ? iphone.fotos.map((foto: any) => getImageUrl(foto.url))
    : [];

  const WHATSAPP_PHONE = process.env.NEXT_PUBLIC_WHATSAPP_PHONE || "";
  const WHATSAPP_MESSAGE = `Hola HaviTech, estoy interesado en comprar el ${iphone.modelo} (${iphone.almacenamiento} - ${iphone.color}) listado a $${iphone.precio}. ¿Aún está disponible?`;
  const whatsappUrl = WHATSAPP_PHONE 
    ? `https://wa.me/${WHATSAPP_PHONE}?text=${encodeURIComponent(WHATSAPP_MESSAGE)}` 
    : "#";

  return (
    <main className="min-h-screen bg-[#0a0a0a] flex items-center justify-center p-4 py-20 md:p-8 relative">
      
      {/* EL TRUCO DEL FONDO: Este Link invisible ocupa toda la pantalla por detrás de la tarjeta.
          Si el usuario hace clic afuera de la tarjeta negra, lo lleva a /#comprar */}
      <Link href="/#comprar" className="absolute inset-0 z-0 cursor-default" aria-label="Cerrar detalles" />

      {/* LA TARJETA CENTRAL (Z-10 para que esté por encima del fondo y no se cierre por accidente) */}
      <div className="w-full max-w-5xl bg-[#111111] rounded-[2rem] border border-white/10 flex flex-col md:flex-row shadow-[0_0_50px_rgba(0,0,0,0.5)] relative z-10">
        
        {/* Botón X explícito (También lleva a /#comprar) */}
        <Link 
          href="/#comprar" 
          className="absolute top-4 right-4 md:top-6 md:right-6 z-50 w-10 h-10 flex items-center justify-center rounded-full bg-black/60 hover:bg-black border border-white/10 text-gray-400 hover:text-white transition-colors"
        >
          <span className="material-symbols-outlined text-xl">close</span>
        </Link>

        {/* Columna Izquierda */}
        <div className="w-full md:w-1/2 shrink-0">
          <ImageGallery urls={urlsAbsolutas} />
        </div>

        {/* Columna Derecha */}
        <div className="w-full md:w-1/2 p-6 md:p-12 flex flex-col">
          <h1 className="text-2xl md:text-4xl font-extrabold text-white mb-6 md:mb-8 pr-12">
            {iphone.modelo}
          </h1>

          <div className="grid grid-cols-2 gap-y-4 md:gap-y-6 gap-x-4 mb-6 md:mb-8">
            <div>
              <span className="text-gray-400 text-xs md:text-sm block mb-1">Precio:</span> 
              <span className="text-white font-bold text-xl md:text-2xl">${iphone.precio}</span>
            </div>
            <div>
              <span className="text-gray-400 text-xs md:text-sm block mb-1">Capacidad:</span> 
              <span className="text-white font-medium text-base md:text-lg">{iphone.almacenamiento}</span>
            </div>
            <div>
              <span className="text-gray-400 text-xs md:text-sm block mb-1">Color:</span> 
              <span className="text-white font-medium text-base md:text-lg">{iphone.color}</span>
            </div>
            <div>
              <span className="text-gray-400 text-xs md:text-sm block mb-1">Estado:</span> 
              <span className="text-[#135bec] font-bold text-base md:text-lg">{iphone.estado}</span>
            </div>
          </div>

          <div className="text-gray-400 text-sm leading-relaxed mb-8 space-y-2 max-h-[150px] overflow-y-auto pr-2">
            {descripLines.map((line: string, index: number) => (
              <p key={index}>{line}</p>
            ))}
          </div>

          <div className="mt-auto">
            <hr className="border-white/5 mb-6" />
            <a
              href={whatsappUrl}
              target="_blank"
              rel="noopener noreferrer"
              className="flex w-full gap-2 cursor-pointer items-center justify-center rounded-2xl h-14 px-4 bg-[#135bec] text-white text-base font-bold transition-all hover:scale-[1.02] shadow-[0_0_20px_rgba(19,91,236,0.3)] glow-primary"
            >
              <span className="material-symbols-outlined text-lg">shopping_bag</span> 
              Comprar ahora
            </a>
          </div>
        </div>
      </div>
    </main>
  );
}