import qs from 'qs';

const STRAPI_URL = process.env.NEXT_PUBLIC_STRAPI_URL || "http://localhost:1337";

// 1. Definimos la interfaz aquí, donde pertenece la lógica de datos
export interface iPhoneProps {
  id: number;
  documentId: string;
  modelo: string;
  precio: number;
  almacenamiento: string;
  color: string;
  estado: string;
  descrip: string;
  fotos: Array<{
    id: number;
    url: string;
    alternativeText?: string;
  }>;
}

// 2. Usamos la interfaz en la promesa de retorno para asegurar que Next.js sepa qué esperar
export async function getLatestIphones(limit: number = 4): Promise<iPhoneProps[]> {
  const query = qs.stringify({
    // 3. Populate quirúrgico: Solo abrimos "fotos" y pedimos solo url y alternativeText.
    // Los campos modelo, precio, etc., ya vienen incluidos por defecto.
    populate: {
      fotos: {
        fields: ['url', 'alternativeText'] 
      }
    },
    pagination: {
      limit: limit,
    },
    sort: ['createdAt:desc'],
  });

  try {
    const res = await fetch(`${STRAPI_URL}/api/catalogos?${query}`, {
      next: { revalidate: 60 }, 
    });

    if (!res.ok) {
      const errorBody = await res.text();
      throw new Error(`Error fetching iPhones ${res.status}: ${errorBody}`);
    }

    const data = await res.json();
    return data.data || []; 

  } catch (error) {
    console.error("Error en getLatestIphones:", error);
    return [];
  }
}

export async function getIphoneByDocumentId(documentId: string): Promise<iPhoneProps | null> {
  // Construimos la consulta filtrando por el documentId exacto
  const query = qs.stringify({
    filters: {
      documentId: {
        $eq: documentId,
      },
    },
    populate: {
      fotos: {
        fields: ['url', 'alternativeText'] // Pedimos las fotos para el carrusel
      }
    }
  });

  try {
    const res = await fetch(`${STRAPI_URL}/api/catalogos?${query}`, {
      // Usamos revalidación corta. Un producto específico debe estar actualizado.
      next: { revalidate: 60 },
    });

    if (!res.ok) {
      throw new Error(`Error fetching iPhone: ${res.status}`);
    }

    const data = await res.json();
    
    // Como usamos 'filters', Strapi devuelve un array. 
    // Tomamos el primer elemento, o devolvemos null si el array está vacío (no existe).
    return data.data.length > 0 ? data.data[0] : null;

  } catch (error) {
    console.error("Error en getIphoneByDocumentId:", error);
    return null;
  }
}